use std::collections::HashMap;

fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    assert!(n >= 2);

    // Map value -> earliest index where it appears.
    // Keeping the earliest index is crucial to achieve lexicographically smallest (p, q).
    let mut earliest: HashMap<u32, usize> = HashMap::new();

    for q in 0..n {
        let v = nums[q];
        if let Some(need) = target.checked_sub(v) {
            if let Some(&p) = earliest.get(&need) {
                // p is the smallest possible for this q, and since we scan q increasing,
                // this is the lexicographically smallest pair overall.
                return (p, q);
            }
        }

        // Record earliest occurrence only.
        earliest.entry(v).or_insert(q);
    }

    // Problem statement guarantees existence of at least one solution.
    unreachable!("A valid pair is guaranteed to exist by the problem assumptions");
}